ALTER TABLE agent_private.platform_grant_receipts ADD CONSTRAINT platform_grant_receipts_issue_contract CHECK(
 (issue_contract_version=1 AND mint_permit_not_after IS NULL) OR
 (issue_contract_version=2 AND mint_permit_not_after IS NOT NULL AND pg_catalog.isfinite(mint_permit_not_after) AND created_at<mint_permit_not_after AND mint_permit_not_after<=created_at+interval '60 seconds'));

