CREATE FUNCTION agent_private.issue_initial_enrollment_grant(p_expected_environment_id uuid,p_operation_id uuid,p_directory_object_id uuid,p_expected_device_id uuid,p_mapping_created_at timestamptz,p_token_sha256 bytea,p_authorization_digest bytea)
RETURNS TABLE(outcome text,diagnostic_code text,environment_id uuid,operation_id uuid,grant_id uuid,directory_object_id uuid,device_id uuid,mapping_created_at timestamptz,created_at timestamptz,expires_at timestamptz,issue_contract_version smallint,mint_permit_not_after timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,agent_private,pg_temp AS $function$
#variable_conflict use_variable
DECLARE v_environment_id uuid;v_receipt agent_private.platform_grant_receipts%ROWTYPE;
BEGIN
 SELECT binding.environment_id INTO v_environment_id FROM agent_private.platform_grant_database_bindings binding WHERE binding.login_role=SESSION_USER::name AND binding.purpose='IssueInitialGrant';
 IF NOT FOUND OR p_expected_environment_id IS NULL OR p_expected_environment_id<>v_environment_id THEN RETURN QUERY SELECT 'Unauthorized','PrivilegeAuditFailed',NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::timestamptz,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 IF p_operation_id IS NULL OR p_operation_id='00000000-0000-0000-0000-000000000000'::uuid OR p_directory_object_id IS NULL OR p_directory_object_id='00000000-0000-0000-0000-000000000000'::uuid OR p_expected_device_id IS NULL OR p_expected_device_id='00000000-0000-0000-0000-000000000000'::uuid OR p_mapping_created_at IS NULL OR NOT pg_catalog.isfinite(p_mapping_created_at) OR p_token_sha256 IS NULL OR pg_catalog.octet_length(p_token_sha256)<>32 OR p_authorization_digest IS NULL OR pg_catalog.octet_length(p_authorization_digest)<>32 THEN RETURN QUERY SELECT 'PermanentRejected','InvalidRequest',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('agent-platform-grant-operation-v1:'||p_operation_id::text,7912040301));
 SELECT receipt.* INTO v_receipt FROM agent_private.platform_grant_receipts receipt WHERE receipt.operation_id=p_operation_id;
 IF NOT FOUND THEN RETURN QUERY SELECT 'PermanentRejected','InvalidMintPermit',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 IF v_receipt.issue_contract_version<>1 OR v_receipt.mint_permit_not_after IS NOT NULL OR v_receipt.environment_id<>v_environment_id OR v_receipt.directory_object_id<>p_directory_object_id OR v_receipt.device_id<>p_expected_device_id OR v_receipt.mapping_created_at<>p_mapping_created_at OR v_receipt.token_sha256<>p_token_sha256 OR v_receipt.authorization_digest<>p_authorization_digest THEN RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 RETURN QUERY SELECT 'AlreadyCreated','None',v_receipt.environment_id,v_receipt.operation_id,v_receipt.grant_id,v_receipt.directory_object_id,v_receipt.device_id,v_receipt.mapping_created_at,v_receipt.created_at,v_receipt.expires_at,v_receipt.issue_contract_version,v_receipt.mint_permit_not_after;
END;$function$;

CREATE FUNCTION agent_private.issue_initial_enrollment_grant(p_expected_environment_id uuid,p_operation_id uuid,p_directory_object_id uuid,p_expected_device_id uuid,p_mapping_created_at timestamptz,p_mint_permit_not_after timestamptz,p_token_sha256 bytea,p_authorization_digest bytea)
RETURNS TABLE(outcome text,diagnostic_code text,environment_id uuid,operation_id uuid,grant_id uuid,directory_object_id uuid,device_id uuid,mapping_created_at timestamptz,created_at timestamptz,expires_at timestamptz,issue_contract_version smallint,mint_permit_not_after timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,agent_private,pg_temp AS $function$
#variable_conflict use_variable
DECLARE v_environment_id uuid;v_receipt agent_private.platform_grant_receipts%ROWTYPE;v_mapping record;v_now timestamptz;v_grant_id uuid;
BEGIN
 SELECT binding.environment_id INTO v_environment_id FROM agent_private.platform_grant_database_bindings binding WHERE binding.login_role=SESSION_USER::name AND binding.purpose='IssueInitialGrant';
 IF NOT FOUND OR p_expected_environment_id IS NULL OR p_expected_environment_id<>v_environment_id THEN RETURN QUERY SELECT 'Unauthorized','PrivilegeAuditFailed',NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::timestamptz,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 IF p_operation_id IS NULL OR p_operation_id='00000000-0000-0000-0000-000000000000'::uuid OR p_directory_object_id IS NULL OR p_directory_object_id='00000000-0000-0000-0000-000000000000'::uuid OR p_expected_device_id IS NULL OR p_expected_device_id='00000000-0000-0000-0000-000000000000'::uuid OR p_mapping_created_at IS NULL OR NOT pg_catalog.isfinite(p_mapping_created_at) OR p_token_sha256 IS NULL OR pg_catalog.octet_length(p_token_sha256)<>32 OR p_authorization_digest IS NULL OR pg_catalog.octet_length(p_authorization_digest)<>32 THEN RETURN QUERY SELECT 'PermanentRejected','InvalidRequest',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('agent-platform-grant-operation-v1:'||p_operation_id::text,7912040301));
 SELECT receipt.* INTO v_receipt FROM agent_private.platform_grant_receipts receipt WHERE receipt.operation_id=p_operation_id;
 IF FOUND THEN
  IF v_receipt.issue_contract_version<>2 OR v_receipt.mint_permit_not_after IS DISTINCT FROM p_mint_permit_not_after OR v_receipt.environment_id<>v_environment_id OR v_receipt.directory_object_id<>p_directory_object_id OR v_receipt.device_id<>p_expected_device_id OR v_receipt.mapping_created_at<>p_mapping_created_at OR v_receipt.token_sha256<>p_token_sha256 OR v_receipt.authorization_digest<>p_authorization_digest THEN RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
  RETURN QUERY SELECT 'AlreadyCreated','None',v_receipt.environment_id,v_receipt.operation_id,v_receipt.grant_id,v_receipt.directory_object_id,v_receipt.device_id,v_receipt.mapping_created_at,v_receipt.created_at,v_receipt.expires_at,v_receipt.issue_contract_version,v_receipt.mint_permit_not_after;RETURN;
 END IF;
 SELECT mapping.device_id,mapping.created_at INTO v_mapping FROM agent_private.lock_agent_device_directory_binding(v_environment_id,p_directory_object_id) mapping;
 IF NOT FOUND OR v_mapping.device_id<>p_expected_device_id OR v_mapping.created_at<>p_mapping_created_at THEN RETURN QUERY SELECT 'PermanentRejected','MappingUnavailable',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 PERFORM 1 FROM agent_private.lock_agent_device(v_environment_id,p_expected_device_id) device WHERE device.state='Active';
 IF NOT FOUND THEN RETURN QUERY SELECT 'PermanentRejected','DeviceUnavailable',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 v_now:=pg_catalog.clock_timestamp();
 IF p_mint_permit_not_after IS NULL OR NOT pg_catalog.isfinite(p_mint_permit_not_after) OR p_mint_permit_not_after>v_now+interval '60 seconds' THEN RETURN QUERY SELECT 'PermanentRejected','InvalidMintPermit',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 IF v_now>=p_mint_permit_not_after THEN RETURN QUERY SELECT 'PermanentRejected','MintPermitExpired',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 IF EXISTS(SELECT 1 FROM agent_private.registrations registration WHERE registration.environment_id=v_environment_id AND registration.device_id=p_expected_device_id AND registration.state='Active') THEN RETURN QUERY SELECT 'PermanentRejected','EnrollmentAlreadyExists',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 IF EXISTS(SELECT 1 FROM agent_private.enrollment_requests request WHERE request.environment_id=v_environment_id AND request.device_id=p_expected_device_id AND request.state IN('PendingIssuance','ExternalPending','Issued','OutcomeUnknown')) THEN RETURN QUERY SELECT 'PermanentRejected','EnrollmentInProgress',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 IF EXISTS(SELECT 1 FROM agent_private.enrollment_grants grant_row WHERE grant_row.environment_id=v_environment_id AND grant_row.device_id=p_expected_device_id AND grant_row.state='Available') THEN RETURN QUERY SELECT 'PermanentRejected','GrantAlreadyAvailable',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 IF EXISTS(SELECT 1 FROM agent_private.enrollment_grants grant_row WHERE grant_row.token_sha256=p_token_sha256) THEN RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_operation_id,NULL::uuid,p_directory_object_id,p_expected_device_id,p_mapping_created_at,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz;RETURN;END IF;
 v_grant_id:=pg_catalog.gen_random_uuid();
 INSERT INTO agent_private.enrollment_grants(environment_id,grant_id,device_id,token_sha256,state,created_at,expires_at) VALUES(v_environment_id,v_grant_id,p_expected_device_id,p_token_sha256,'Available',v_now,v_now+interval '600 seconds');
 INSERT INTO agent_private.platform_grant_receipts(environment_id,operation_id,grant_id,directory_object_id,device_id,mapping_created_at,token_sha256,authorization_digest,created_at,expires_at,issue_contract_version,mint_permit_not_after) VALUES(v_environment_id,p_operation_id,v_grant_id,p_directory_object_id,p_expected_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,v_now,v_now+interval '600 seconds',2,p_mint_permit_not_after);
 RETURN QUERY SELECT 'Created','None',v_environment_id,p_operation_id,v_grant_id,p_directory_object_id,p_expected_device_id,p_mapping_created_at,v_now,v_now+interval '600 seconds',2::smallint,p_mint_permit_not_after;
END;$function$;

