BEGIN
 SELECT binding.environment_id INTO v_environment_id FROM agent_private.platform_grant_database_bindings binding WHERE binding.login_role=SESSION_USER::name AND binding.purpose='RevokeInitialGrant';
 IF NOT FOUND OR p_expected_environment_id IS NULL OR p_expected_environment_id<>v_environment_id THEN RETURN QUERY SELECT 'Unauthorized','PrivilegeAuditFailed',NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::timestamptz,NULL::bytea,NULL::bytea,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 IF p_operation_id IS NULL OR p_operation_id='00000000-0000-0000-0000-000000000000'::uuid OR p_grant_id IS NULL OR p_grant_id='00000000-0000-0000-0000-000000000000'::uuid OR p_directory_object_id IS NULL OR p_directory_object_id='00000000-0000-0000-0000-000000000000'::uuid OR p_device_id IS NULL OR p_device_id='00000000-0000-0000-0000-000000000000'::uuid OR p_mapping_created_at IS NULL OR NOT pg_catalog.isfinite(p_mapping_created_at) OR p_token_sha256 IS NULL OR pg_catalog.octet_length(p_token_sha256)<>32 OR p_authorization_digest IS NULL OR pg_catalog.octet_length(p_authorization_digest)<>32 OR p_created_at IS NULL OR NOT pg_catalog.isfinite(p_created_at) OR p_expires_at IS NULL OR NOT pg_catalog.isfinite(p_expires_at) OR p_mapping_created_at>p_created_at OR p_expires_at<>p_created_at+interval '600 seconds' OR NOT ((p_issue_contract_version=1 AND p_mint_permit_not_after IS NULL) OR (p_issue_contract_version=2 AND p_mint_permit_not_after IS NOT NULL AND pg_catalog.isfinite(p_mint_permit_not_after) AND p_created_at<p_mint_permit_not_after AND p_mint_permit_not_after<=p_created_at+interval '60 seconds')) THEN
  RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 SELECT receipt.* INTO v_receipt FROM agent_private.platform_grant_receipts receipt WHERE receipt.operation_id=p_operation_id;
 IF NOT FOUND THEN RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 IF v_receipt.environment_id<>v_environment_id OR v_receipt.grant_id<>p_grant_id OR v_receipt.directory_object_id<>p_directory_object_id OR v_receipt.device_id<>p_device_id OR v_receipt.mapping_created_at<>p_mapping_created_at OR v_receipt.token_sha256<>p_token_sha256 OR v_receipt.authorization_digest<>p_authorization_digest OR v_receipt.created_at<>p_created_at OR v_receipt.expires_at<>p_expires_at OR v_receipt.issue_contract_version<>p_issue_contract_version OR v_receipt.mint_permit_not_after IS DISTINCT FROM p_mint_permit_not_after THEN
  RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 SELECT grant_row.state,grant_row.device_id,grant_row.token_sha256,grant_row.created_at,grant_row.expires_at,grant_row.consumed_at,grant_row.revoked_at INTO v_grant FROM agent_private.enrollment_grants grant_row WHERE grant_row.environment_id=v_environment_id AND grant_row.grant_id=p_grant_id;
 v_now:=pg_catalog.clock_timestamp();
 IF NOT FOUND OR v_grant.device_id<>p_device_id OR v_grant.token_sha256<>p_token_sha256 OR v_grant.created_at<>p_created_at OR v_grant.expires_at<>p_expires_at OR v_grant.state NOT IN('Available','Consumed','Revoked') OR
    (v_grant.state='Consumed' AND (v_grant.consumed_at IS NULL OR NOT pg_catalog.isfinite(v_grant.consumed_at) OR v_grant.consumed_at<p_created_at OR v_grant.consumed_at>=p_expires_at OR v_grant.consumed_at>v_now)) OR
    (v_grant.state='Revoked' AND (v_grant.revoked_at IS NULL OR NOT pg_catalog.isfinite(v_grant.revoked_at) OR v_grant.revoked_at<p_created_at OR v_grant.revoked_at>v_now)) THEN
  RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 RETURN QUERY SELECT CASE WHEN v_grant.state='Available' AND p_expires_at<=v_now THEN 'Expired' ELSE v_grant.state END,'None',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,v_now,CASE WHEN v_grant.state='Consumed' THEN v_grant.consumed_at WHEN v_grant.state='Revoked' THEN v_grant.revoked_at ELSE NULL::timestamptz END;
END;$function$;

CREATE FUNCTION agent_private.read_initial_enrollment_grant(p_expected_environment_id uuid,p_operation_id uuid,p_grant_id uuid,p_directory_object_id uuid,p_device_id uuid,p_mapping_created_at timestamptz,p_token_sha256 bytea,p_authorization_digest bytea,p_created_at timestamptz,p_expires_at timestamptz)
RETURNS TABLE(state text,diagnostic_code text,environment_id uuid,operation_id uuid,grant_id uuid,directory_object_id uuid,device_id uuid,mapping_created_at timestamptz,token_sha256 bytea,authorization_digest bytea,created_at timestamptz,expires_at timestamptz,issue_contract_version smallint,mint_permit_not_after timestamptz,observed_at timestamptz,state_changed_at timestamptz)
