 BEGIN RETURN QUERY SELECT * FROM agent_private.read_initial_enrollment_grant(p_expected_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,1::smallint,NULL::timestamptz); END;
