CREATE FUNCTION agent_private.revoke_initial_enrollment_grant(p_expected_environment_id uuid,p_revocation_operation_id uuid,p_operation_id uuid,p_grant_id uuid,p_directory_object_id uuid,p_device_id uuid,p_mapping_created_at timestamptz,p_token_sha256 bytea,p_authorization_digest bytea,p_created_at timestamptz,p_expires_at timestamptz,p_issue_contract_version smallint,p_mint_permit_not_after timestamptz,p_revoke_authorization_digest bytea)
RETURNS TABLE(outcome text,diagnostic_code text,environment_id uuid,revocation_operation_id uuid,issue_operation_id uuid,grant_id uuid,directory_object_id uuid,device_id uuid,mapping_created_at timestamptz,token_sha256 bytea,issue_authorization_digest bytea,issue_created_at timestamptz,issue_expires_at timestamptz,issue_contract_version smallint,issue_mint_permit_not_after timestamptz,revoke_authorization_digest bytea,disposition text,completed_at timestamptz,effective_revoked_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,agent_private,pg_temp AS $function$
#variable_conflict use_variable
DECLARE v_environment_id uuid;v_issue agent_private.platform_grant_receipts%ROWTYPE;v_existing agent_private.platform_grant_revocation_receipts%ROWTYPE;v_grant record;v_now timestamptz;v_disposition text;v_effective timestamptz;
BEGIN
 SELECT binding.environment_id INTO v_environment_id FROM agent_private.platform_grant_database_bindings binding WHERE binding.login_role=SESSION_USER::name AND binding.purpose='RevokeInitialGrant';
 IF NOT FOUND OR p_expected_environment_id IS NULL OR p_expected_environment_id<>v_environment_id THEN RETURN QUERY SELECT 'Unauthorized','PrivilegeAuditFailed',NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::timestamptz,NULL::bytea,NULL::bytea,NULL::timestamptz,NULL::timestamptz,NULL::smallint,NULL::timestamptz,NULL::bytea,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 IF p_revocation_operation_id IS NULL OR p_revocation_operation_id='00000000-0000-0000-0000-000000000000'::uuid OR p_operation_id IS NULL OR p_operation_id='00000000-0000-0000-0000-000000000000'::uuid OR p_grant_id IS NULL OR p_grant_id='00000000-0000-0000-0000-000000000000'::uuid OR p_directory_object_id IS NULL OR p_directory_object_id='00000000-0000-0000-0000-000000000000'::uuid OR p_device_id IS NULL OR p_device_id='00000000-0000-0000-0000-000000000000'::uuid OR p_mapping_created_at IS NULL OR NOT pg_catalog.isfinite(p_mapping_created_at) OR p_token_sha256 IS NULL OR pg_catalog.octet_length(p_token_sha256)<>32 OR p_authorization_digest IS NULL OR pg_catalog.octet_length(p_authorization_digest)<>32 OR p_created_at IS NULL OR NOT pg_catalog.isfinite(p_created_at) OR p_expires_at IS NULL OR NOT pg_catalog.isfinite(p_expires_at) OR p_mapping_created_at>p_created_at OR p_expires_at<>p_created_at+interval '600 seconds' OR NOT ((p_issue_contract_version=1 AND p_mint_permit_not_after IS NULL) OR (p_issue_contract_version=2 AND p_mint_permit_not_after IS NOT NULL AND pg_catalog.isfinite(p_mint_permit_not_after) AND p_created_at<p_mint_permit_not_after AND p_mint_permit_not_after<=p_created_at+interval '60 seconds')) OR p_revoke_authorization_digest IS NULL OR pg_catalog.octet_length(p_revoke_authorization_digest)<>32 THEN
  RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('agent-platform-grant-revocation-operation-v1:'||p_revocation_operation_id::text,7912040301));
 SELECT receipt.* INTO v_existing FROM agent_private.platform_grant_revocation_receipts receipt WHERE receipt.revocation_operation_id=p_revocation_operation_id;
 IF FOUND THEN
  IF v_existing.environment_id<>v_environment_id OR v_existing.issue_operation_id<>p_operation_id OR v_existing.grant_id<>p_grant_id OR v_existing.directory_object_id<>p_directory_object_id OR v_existing.device_id<>p_device_id OR v_existing.mapping_created_at<>p_mapping_created_at OR v_existing.token_sha256<>p_token_sha256 OR v_existing.issue_authorization_digest<>p_authorization_digest OR v_existing.issue_created_at<>p_created_at OR v_existing.issue_expires_at<>p_expires_at OR v_existing.issue_contract_version<>p_issue_contract_version OR v_existing.issue_mint_permit_not_after IS DISTINCT FROM p_mint_permit_not_after OR v_existing.revoke_authorization_digest<>p_revoke_authorization_digest THEN
   RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
  END IF;
  RETURN QUERY SELECT 'AlreadyCompleted','None',v_existing.environment_id,v_existing.revocation_operation_id,v_existing.issue_operation_id,v_existing.grant_id,v_existing.directory_object_id,v_existing.device_id,v_existing.mapping_created_at,v_existing.token_sha256,v_existing.issue_authorization_digest,v_existing.issue_created_at,v_existing.issue_expires_at,v_existing.issue_contract_version,v_existing.issue_mint_permit_not_after,v_existing.revoke_authorization_digest,v_existing.disposition,v_existing.completed_at,v_existing.effective_revoked_at;RETURN;
 END IF;
 SELECT receipt.* INTO v_issue FROM agent_private.platform_grant_receipts receipt WHERE receipt.operation_id=p_operation_id;
 IF NOT FOUND THEN RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 IF v_issue.environment_id<>v_environment_id OR v_issue.grant_id<>p_grant_id OR v_issue.directory_object_id<>p_directory_object_id OR v_issue.device_id<>p_device_id OR v_issue.mapping_created_at<>p_mapping_created_at OR v_issue.token_sha256<>p_token_sha256 OR v_issue.authorization_digest<>p_authorization_digest OR v_issue.created_at<>p_created_at OR v_issue.expires_at<>p_expires_at OR v_issue.issue_contract_version<>p_issue_contract_version OR v_issue.mint_permit_not_after IS DISTINCT FROM p_mint_permit_not_after THEN
  RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('agent-platform-grant-environment-v1:'||v_environment_id::text||':grant:'||p_grant_id::text,7912040301));
 SELECT receipt.* INTO v_existing FROM agent_private.platform_grant_revocation_receipts receipt WHERE receipt.environment_id=v_environment_id AND receipt.grant_id=p_grant_id;
 IF FOUND THEN RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 SELECT grant_row.state,grant_row.device_id,grant_row.token_sha256,grant_row.created_at,grant_row.expires_at,grant_row.consumed_at,grant_row.revoked_at INTO v_grant FROM agent_private.enrollment_grants grant_row WHERE grant_row.environment_id=v_environment_id AND grant_row.grant_id=p_grant_id AND grant_row.state='Available' FOR UPDATE;
 IF FOUND THEN
  IF v_grant.device_id<>p_device_id OR v_grant.token_sha256<>p_token_sha256 OR v_grant.created_at<>p_created_at OR v_grant.expires_at<>p_expires_at OR v_grant.consumed_at IS NOT NULL OR v_grant.revoked_at IS NOT NULL THEN
   RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
  END IF;
  v_now:=pg_catalog.clock_timestamp();v_disposition:=CASE WHEN v_grant.expires_at<=v_now THEN 'Expired' ELSE 'Revoked' END;v_effective:=v_now;
  UPDATE agent_private.enrollment_grants grant_row SET state='Revoked',revoked_at=v_now WHERE grant_row.environment_id=v_environment_id AND grant_row.grant_id=p_grant_id AND grant_row.device_id=p_device_id AND grant_row.token_sha256=p_token_sha256 AND grant_row.created_at=p_created_at AND grant_row.expires_at=p_expires_at AND grant_row.state='Available';
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='grant state changed';END IF;
 ELSE
  SELECT grant_row.state,grant_row.device_id,grant_row.token_sha256,grant_row.created_at,grant_row.expires_at,grant_row.consumed_at,grant_row.revoked_at INTO v_grant FROM agent_private.enrollment_grants grant_row WHERE grant_row.environment_id=v_environment_id AND grant_row.grant_id=p_grant_id;
  v_now:=pg_catalog.clock_timestamp();
  IF NOT FOUND OR v_grant.device_id<>p_device_id OR v_grant.token_sha256<>p_token_sha256 OR v_grant.created_at<>p_created_at OR v_grant.expires_at<>p_expires_at OR v_grant.state NOT IN('Consumed','Revoked') OR
     (v_grant.state='Consumed' AND (v_grant.consumed_at IS NULL OR NOT pg_catalog.isfinite(v_grant.consumed_at) OR v_grant.consumed_at<p_created_at OR v_grant.consumed_at>=p_expires_at OR v_grant.consumed_at>v_now)) OR
     (v_grant.state='Revoked' AND (v_grant.revoked_at IS NULL OR NOT pg_catalog.isfinite(v_grant.revoked_at) OR v_grant.revoked_at<p_created_at OR v_grant.revoked_at>v_now)) THEN
   RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
  END IF;
  IF v_grant.state='Consumed' THEN v_disposition:='Consumed';v_effective:=NULL;
  ELSE v_disposition:='AlreadyRevoked';v_effective:=v_grant.revoked_at;END IF;
 END IF;
 INSERT INTO agent_private.platform_grant_revocation_receipts(environment_id,revocation_operation_id,issue_operation_id,grant_id,directory_object_id,device_id,mapping_created_at,token_sha256,issue_authorization_digest,issue_created_at,issue_expires_at,issue_contract_version,issue_mint_permit_not_after,revoke_authorization_digest,disposition,completed_at,effective_revoked_at)
 VALUES(v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,p_revoke_authorization_digest,v_disposition,v_now,v_effective);
 RETURN QUERY SELECT 'Completed','None',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_issue_contract_version,p_mint_permit_not_after,p_revoke_authorization_digest,v_disposition,v_now,v_effective;
END;$function$;

