ALTER FUNCTION agent_private.audit_platform_grant_privileges(uuid,name,name) OWNER TO :"agent_platform_grant_definer_role";
REVOKE ALL ON FUNCTION agent_private.audit_platform_grant_privileges(uuid,name,name) FROM PUBLIC;
DO $grant_bound_platform_roles$
DECLARE
 v_binding record;
BEGIN
 FOR v_binding IN SELECT login_role,purpose FROM agent_private.platform_grant_database_bindings ORDER BY login_role LOOP
  IF v_binding.purpose='IssueInitialGrant' THEN
   EXECUTE pg_catalog.format('GRANT EXECUTE ON FUNCTION agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,bytea,bytea),agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,timestamptz,bytea,bytea),agent_private.audit_platform_grant_privileges(uuid,name,name) TO %I',v_binding.login_role);
  ELSIF v_binding.purpose='RevokeInitialGrant' THEN
   EXECUTE pg_catalog.format('GRANT EXECUTE ON FUNCTION agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz),agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz),agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,bytea),agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz,bytea),agent_private.audit_platform_grant_privileges(uuid,name,name) TO %I',v_binding.login_role);
  ELSE
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid platform grant binding';
  END IF;
 END LOOP;
END
$grant_bound_platform_roles$;
